// Decides who is due for which message, and renders every merge field.
// Emits ONE item per message to send. Emits nothing when nothing is due,
// which is the normal case on most of the 288 runs a day.

// ---- switches -------------------------------------------------------------
// Keep SMS_ENABLED false until BOTH are true:
//   1. Twilio A2P 10DLC campaign approved, and
//   2. the iClosed form's consent line covers marketing SMS.
// See TWILIO_RUNBOOK.md. Email works fine on its own until then.
const SMS_ENABLED = false;
const SMS_DELAY_HOURS = 4;          // after the email, not after abandonment
const MAX_AGE_HOURS = 72;           // past this a lead is cold; stop chasing
const QUIET_START = 21;             // no sends at/after 21:00 recipient-local
const QUIET_END = 8;                // no sends before 08:00 recipient-local
const DEFAULT_TZ = 'America/New_York';

const now = new Date();
const out = [];

// ---- date helpers ---------------------------------------------------------
// Next two business days, rendered per MESSAGE_TEMPLATES.md §Date logic.
function dayOptions(from, tz) {
  const nameOf = (d) => d.toLocaleDateString('en-US', { weekday: 'long', timeZone: tz });
  const dowOf = (d) => d.toLocaleDateString('en-US', { weekday: 'short', timeZone: tz });
  const opts = [];
  for (let i = 1; i <= 7 && opts.length < 2; i++) {
    const d = new Date(from.getTime() + i * 86400000);
    const dow = dowOf(d);
    if (dow === 'Sat' || dow === 'Sun') continue;
    // "tomorrow" only when it is literally the next calendar day.
    opts.push(i === 1 ? 'tomorrow' : nameOf(d));
  }
  while (opts.length < 2) opts.push('later this week');
  return opts;
}

function localHour(d, tz) {
  const h = d.toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: tz });
  return parseInt(h, 10);
}

function validTz(tz) {
  if (!tz) return DEFAULT_TZ;
  try { new Date().toLocaleString('en-US', { timeZone: tz }); return tz; }
  catch (e) { return DEFAULT_TZ; }
}

// ---- selection ------------------------------------------------------------
for (const item of $input.all()) {
  const r = item.json;
  if (String(r.status || '') !== 'pending') continue;

  const createdAt = new Date(r.created_at);
  if (isNaN(createdAt)) continue;
  const ageHours = (now - createdAt) / 3600000;

  // Too old to be worth a message, and too old to keep scanning every 5 min.
  if (ageHours > MAX_AGE_HOURS) {
    out.push({ json: { ...r, action: 'expire' } });
    continue;
  }

  const tz = validTz(r.timezone);
  const hour = localHour(now, tz);
  const inQuietHours = hour >= QUIET_START || hour < QUIET_END;

  const emailSent = !!String(r.email_sent_at || '').trim();
  const smsSent = !!String(r.sms_sent_at || '').trim();
  const dueAt = new Date(r.follow_up_due_at);
  const emailDue = !emailSent && !isNaN(dueAt) && now >= dueAt && !!r.email;

  const smsDueAt = emailSent
    ? new Date(new Date(r.email_sent_at).getTime() + SMS_DELAY_HOURS * 3600000)
    : null;
  const smsDue = SMS_ENABLED && emailSent && !smsSent && !!r.phone
    && smsDueAt && !isNaN(smsDueAt) && now >= smsDueAt;

  if (!emailDue && !smsDue) continue;

  // Quiet hours defer rather than skip — the row stays pending and the next
  // run picks it up. Email is exempt: an inbox is not a buzzing phone.
  if (smsDue && !emailDue && inQuietHours) continue;

  const [d1, d2] = dayOptions(now, tz);
  const greetingName = r.first_name ? String(r.first_name) : '';

  out.push({ json: {
    ...r,
    action: emailDue ? 'email' : 'sms',
    first_name: greetingName,
    // Subject and salutation degrade gracefully when the name is unusable.
    subject: greetingName
      ? greetingName + ', still want that social media strategy call?'
      : 'Still want that social media strategy call?',
    salutation: greetingName ? 'Hi ' + greetingName + ',' : 'Hi,',
    sms_salutation: greetingName
      ? 'Hi ' + greetingName + ", it's Kasper from Synchro Social."
      : "Hi, it's Kasper from Synchro Social.",
    day_option_1: d1,
    day_option_2: d2,
    booking_url: 'https://synchrosocial.com/apply'
  } });
}

return out;

// THE GATE. Nothing else in this system matters as much as this node:
// messaging "you didn't book" to someone who DID book is the one failure
// that costs a sale rather than just missing one.
//
// A contact carrying a deal_id means the booking router already created a
// deal for them, i.e. they reached at least 'Call Scheduled'. Chasing them
// is wrong. Same for anyone already a customer.
//
// Output 0 = safe to send. Output 1 = suppress.
const send = [];
const suppress = [];

for (const item of $input.all()) {
  const r = item.json;

  if (r.action === 'expire') {
    suppress.push({ json: { ...r, suppressed_reason: 'expired' } });
    continue;
  }

  // The HubSpot node is set to continue on error and always output data, so
  // a CRM hiccup surfaces here as a missing contact rather than a thrown
  // execution. Fail SAFE: no confirmation that they are unbooked means we
  // do not send. A missed recovery email is cheap; a wrong one is not.
  if (r.error || r.__hubspotError) {
    continue; // leave pending, retry on the next 5-minute run
  }

  const dealId = String(r.deal_id || '').trim();
  const lifecycle = String(r.lifecyclestage || '').trim().toLowerCase();

  if (dealId) {
    suppress.push({ json: { ...r, suppressed_reason: 'already_booked' } });
    continue;
  }
  if (lifecycle === 'customer' || lifecycle === 'opportunity') {
    suppress.push({ json: { ...r, suppressed_reason: 'existing_' + lifecycle } });
    continue;
  }

  send.push({ json: r });
}

return [send, suppress];
